//! 🔤️ Original UTF-8 bytes advance under the actual selected work limit.
use semio_framework_test_fixtures::fixture_text;
use semio_framework_value_clone_source::RetainedCloneSource;
use semio_framework_value_clone_source_testing::FixtureSourceBirth;
use semio_framework_value_retained_clone::*;
#[path="../../🧪️tests/⏱️effect/🦀️.rs"]
mod effect;
use semio_framework_value_testing_allocator::observe_retirement_allocations;

fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}

#[test]
fn original_string_one_work_byte_survives_partial_utf8_and_close(){
 let corpus:serde_json::Value=serde_json::from_str(fixture_text!("../../../../../📡️replication/🎮️mutation/🧳️retained/🔺️diff/🪢️sequence/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let law=&corpus["diagnosticText"];let text=law["pattern"].as_str().unwrap().repeat(law["repetitions"].as_u64().unwrap()as usize);assert_eq!(text.len(),law["bytes"].as_u64().unwrap()as usize);
 for cancel in [Some(2usize),None]{let source=RetainedCloneSource::<String>::from_owner(text.clone());let original=source.borrow().get().as_ptr();let mut cursor=String::retained_clone_cursor();let mut bytes=0usize;let mut turns=0usize;loop{let limit=if turns==0{3}else{1};let d=cursor.advance_demands(source.borrow(),4096,limit).unwrap();let q=cursor.advance_work_demand(source.borrow(),4096,limit).unwrap();assert!(q<=limit);let g=grant(d);let denied=effect::advance(&mut cursor,source.borrow(),4096,0,g);assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());let(turn,heap)=observe_retirement_allocations(||effect::advance(&mut cursor,source.borrow(),4096,limit,g));assert!(turn.work<=u128::from(q));let step=turn.result.unwrap();let progress=step.progress();assert!(progress.fits(g));assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));if d.copy_bytes==1+std::mem::size_of::<usize>(){let payload=progress.copied_bytes-std::mem::size_of::<usize>();bytes+=payload;assert_eq!(turn.work,payload as u128)}assert_eq!(source.borrow().get().as_ptr(),original);turns+=1;assert!(turns<text.len()+16);if cancel==Some(bytes){assert!(!cursor.output_ready());assert!({let g=grant(cursor.take_demand().unwrap());effect::take(&mut cursor,g)}.result.unwrap().is_none());break}if matches!(step,RetainedCloneStep::Complete(_)){assert_eq!(bytes,text.len());assert!(cursor.output_ready());let(turn,heap)=observe_retirement_allocations(||{let g=grant(cursor.take_demand().unwrap());effect::take(&mut cursor,g)});assert_eq!(heap,(0,0));let(output,_)=turn.result.unwrap().unwrap();assert_eq!(output,text);let mut slot=Some(output);let mut retirement=RetainedCloneClose::default();let mut retire_turns=0;while slot.is_some()||!retirement.is_empty(){retire_turns+=1;assert!(retire_turns<10000);let d=retirement.next_owner_demands::<String>(slot.is_some(),&None,4096).unwrap();let g=grant(d);if !retirement.is_empty(){effect::step_granted(&mut retirement,g).result.unwrap();}else{effect::begin_granted(&mut retirement,&mut slot,g).result.unwrap();}}break}}
 effect::begin_close(&mut cursor);let mut close_turns=0;while !cursor.terminal_is_empty(){close_turns+=1;assert!(close_turns<10000);let d=cursor.close_demands(4096).unwrap();let turn=effect::close_step(&mut cursor,grant(d));turn.result.unwrap();}drop(cursor);drop(source);}
}
